  // TEA: 450 * 1 = 450, no discount, 9% vat = 40.5 -> 40
  // total: 1980 + 450 - 0 - 0 + 416 + 40 = 2886 cents
  const result = recordPayment(issued.value, { amount: 2886, date: '2026-10-07' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment: cannot record payment on paid invoice', () => {
